package cc.ataglace.molebutter.marketplaceelevenst.internal;
import java.time.Instant;
import java.util.*;
import java.util.function.Consumer;
import org.springframework.stereotype.Component;
import tools.jackson.databind.ObjectMapper;
import cc.ataglace.molebutter.identity.api.BusinessAccess;
import cc.ataglace.molebutter.marketplace.api.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceDrafts.Document;
import cc.ataglace.molebutter.media.api.*;
import static cc.ataglace.molebutter.marketplace.api.MarketplaceWriteGateway.*;
import static cc.ataglace.molebutter.marketplace.api.PartnerFormSupport.*;
@Component
final class ElevenstWriter implements MarketplaceWriteGateway {
 private final BusinessAccess access;private final ElevenstCatalog catalog;private final ElevenstDocuments docs;private final ObjectMapper json;private final ImageInspection inspection;private final ImageAssets assets;private final R2Images r2;
 ElevenstWriter(BusinessAccess access,ElevenstCatalog catalog,ElevenstDocuments docs,ObjectMapper json,ImageInspection inspection,ImageAssets assets,R2Images r2){this.access=access;this.catalog=catalog;this.docs=docs;this.json=json;this.inspection=inspection;this.assets=assets;this.r2=r2;}
 public String market(){return "ELEVENST";}public String accountKey(){return catalog.client.account();}public Document projectChanges(Document d,List<MarketplaceEditing.Change> changes){return docs.apply(d,changes);}
 public Prepared prepare(Long actor,Document d,Mapping mapping,boolean requested){return prepareSelected(actor,d,mapping,false,docs.newDocument(d),List.of());}
 public Prepared prepareSelected(Long actor,Document reference,Mapping mapping,boolean requested,Document observed,List<MarketplaceEditing.Change> changes){access.productActor(actor,true);check(mapping);var desired=docs.apply(observed,changes);var input=docs.input(desired);var steps=new ArrayList<Step>();
  if(mapping==null){MarketplaceCommonSettings.validate(desired);ElevenstRules.validate(input,true);verifyChoices(actor,input);inspection.require(actor,docs.images(desired,Set.of()));String body=wire(actor,input,null);steps.add(step(actor,Type.CREATE,null,"POST","/rest/prodservices/product",body,Map.of(),Map.of()));}
  else{var snapshot=catalog.snapshot(mapping.sellerProductId());if(!snapshot.supported())throw invalid(snapshot.observation().warning());var latest=docs.observe(actor,reference,mapping);var rebased=docs.rebase(observed,latest,changes);if(!rebased.conflicts().isEmpty())throw new MarketplaceEditConflict(rebased.conflicts().getFirst().path(),json.valueToTree(rebased.conflicts().getFirst().before()),json.valueToTree(rebased.conflicts().getFirst().current()),json.valueToTree(rebased.conflicts().getFirst().desired()));desired=docs.apply(latest,changes);input=docs.input(desired);if(changes.stream().anyMatch(c->c.path().matches("partner\\.fields\\.(aplBgnDy|aplEndDy|selPrdClfCd|selTermUseYn)")))ElevenstRules.validatePeriod(input);ElevenstRules.validate(input,false);
   var before=parts(docs.input(latest));var after=parts(input);var effective=new ArrayList<>(PartnerFormSupport.diff(docs.input(latest),input,json));
   var priceKeys=Set.of("selPrc","cuponcheck","dscAmtPercnt","cupnDscMthdCd","cupnUseLmtDyYn","cupnIssEndDy");var prices=effective.stream().filter(c->c.path().startsWith("partner.fields.")&&priceKeys.contains(c.path().substring(15))).toList();
   if(!prices.isEmpty()){long oldPrice=ElevenstRules.number(ElevenstRules.field(docs.input(latest),"selPrc"),"기존 판매가"),newPrice=ElevenstRules.number(ElevenstRules.field(input,"selPrc"),"판매가");if(newPrice*10<oldPrice*2||newPrice*2>oldPrice*3)throw invalid("판매가는 기존가 대비 50% 인상·80% 인하 범위로 수정해 주세요.");var f=new LinkedHashMap<String,Object>();for(String k:priceKeys)if(input.fields().containsKey(k))f.put(k,input.fields().get(k));steps.add(step(actor,Type.PRICE,null,"POST","/rest/prodservices/product/priceCoupon/"+mapping.sellerProductId(),ElevenstWire.values("Product",f),priceGroup(before,priceKeys),priceGroup(after,priceKeys)));}
   var original=docs.input(latest);if(effective.stream().anyMatch(c->c.path().equals("partner.options"))){if(input.options().size()!=original.options().size())throw invalid("기존 옵션 추가·삭제는 전체 구성 확인 전 지원하지 않습니다.");for(var row:input.options()){
    var old=original.options().stream().filter(o->o.id().equals(row.id())).findFirst().orElseThrow(()->invalid("옵션 연결을 확인해 주세요."));if(!Objects.equals(old.name(),row.name())||!Objects.equals(old.price(),row.price())||!Objects.equals(old.sku(),row.sku())||!Objects.equals(old.attributes(),row.attributes())||!Objects.equals(old.usable(),row.usable()))throw invalid("기존 옵션은 재고만 개별 수정할 수 있습니다. 옵션 구성·추가금 변경은 최신 전체 구성 확인이 필요합니다.");
    if(!Objects.equals(old.quantity(),row.quantity())){var link=mapping.options().stream().filter(o->o.optionId().equals(row.id())).findFirst().orElseThrow();var stock=snapshot.stocks().stream().filter(s->s.remoteId().equals(link.sellerProductItemId())).findFirst().orElseThrow();if(stock.weight().isBlank())throw invalid("옵션 무게가 미확인이라 재고 수정을 진행할 수 없습니다.");var f=Map.of("prdNo",mapping.sellerProductId(),"prdStckNo",stock.remoteId(),"stckQty",row.quantity(),"optWght",stock.weight());steps.add(step(actor,Type.STOCK,row.id(),"PUT","/rest/prodservices/stockqty/"+stock.remoteId(),ElevenstWire.values("ProductStock",f),Map.of("quantity",old.quantity()),Map.of("quantity",row.quantity())));}
   }}
   var description=effective.stream().filter(c->c.path().equals("partner.description")).toList();if(!description.isEmpty()){inspection.require(actor,docs.images(desired,docs.images(latest,Set.of()).stream().map(ImageInspection.Input::url).collect(java.util.stream.Collectors.toSet())).stream().filter(i->i.role().equals("DESCRIPTION")).toList());String html=EditedImages.description(actor,input.description(),original.description(),r2,assets);steps.add(step(actor,Type.PRODUCT,null,"POST","/rest/prodservices/updateProductDetailCont/"+mapping.sellerProductId(),ElevenstWire.values("ProductDetailCont",Map.of("prdDescContClob",html)),selected(before,description),Map.of("description",html)));}
   var full=effective.stream().filter(c->!prices.contains(c)&&!description.contains(c)&&!c.path().equals("partner.options")).toList();if(!full.isEmpty()){
    if(!snapshot.wholeReadable())throw invalid("현재 응답에 전체 수정으로 보존할 수 없는 항목이 있습니다. 가격·재고·상세설명 전용 수정을 사용해 주세요.");
    if(full.stream().anyMatch(c->c.path().equals("partner.fields.dispCtgrNo")))throw invalid("기존 상품의 카테고리는 변경하지 않습니다. 신규 상품 정책과 상위 분류 확인이 필요합니다.");
    for(var f:ElevenstRules.SCHEMA.fields())if(f.required()&&!original.fields().containsKey(f.key()))throw invalid("전체 수정에 필요한 최신 "+f.label()+" 값이 미확인입니다. 가격·재고·상세설명은 개별 수정할 수 있습니다.");
    ElevenstRules.validate(input,true,changes.stream().anyMatch(c->c.path().matches("partner\\.fields\\.(aplBgnDy|aplEndDy|selPrdClfCd|selTermUseYn)")));verifyChoices(actor,input);var existing=docs.images(latest,Set.of()).stream().map(ImageInspection.Input::url).collect(java.util.stream.Collectors.toSet());inspection.require(actor,docs.images(desired,existing));String body=wire(actor,input,original);if(full.stream().anyMatch(c->c.path().equals("partner.images")))for(int n=input.images().size()+1;n<=4;n++)body=body.replace("</Product>",ElevenstXml.element("prdImage0"+n,"")+"</Product>");
    body=body.replaceAll("(?s)<ProductOption>.*?</ProductOption>","").replaceAll("<prdSelQty>.*?</prdSelQty>","").replace("</Product>",ElevenstXml.element("optUpdateYn","N")+"</Product>");steps.addFirst(step(actor,Type.PRODUCT,null,"PUT","/rest/prodservices/product/"+mapping.sellerProductId(),body,before,selected(after,full)));
   }
  }
  var visible=changes.stream().map(c->new Change(c.path(),"최신 조회값","입력값")).toList();return new Prepared(accountKey(),mapping,List.copyOf(steps),visible,Instant.now(),List.of(),new EditIntent(observed,List.copyOf(changes)),market());
 }
 private String wire(Long actor,PartnerEditor.Input i,PartnerEditor.Input previous){return ElevenstWire.create(i,image->{String url;if(image.assetId()!=null){if(assets.editedMetadata(actor,image.assetId())==null)throw invalid("기존 로컬 이미지는 R2에서 다시 선택해 주세요.");url=assets.submissionUrl(actor,image.assetId());}else if(previous!=null&&previous.images().stream().anyMatch(v->v.url().equals(image.url())))url=image.url();else url=r2.resolve(actor,image.url()).url();if(!url.matches("[\\x21-\\x7e]+"))throw invalid("11번가 이미지 주소에 한글·공백이 있습니다. 다른 이미지 또는 서버 편집본을 선택해 주세요.");return url;},html->EditedImages.description(actor,html,previous==null?null:previous.description(),r2,assets));}
 private void verifyChoices(Long actor,PartnerEditor.Input i){String out=ElevenstRules.field(i,"addrSeqOut"),in=ElevenstRules.field(i,"addrSeqIn");if(catalog.addresses(actor,"outbound").stream().noneMatch(a->a.code().equals(out))||catalog.addresses(actor,"return").stream().noneMatch(a->a.code().equals(in)))throw invalid("11번가 주소록에서 출고지·반품지를 다시 선택해 주세요.");if(catalog.categories(actor).stream().noneMatch(c->c.id().equals(ElevenstRules.field(i,"dispCtgrNo"))&&c.leaf()))throw invalid("최하위 카테고리를 선택해 주세요.");String template=ElevenstRules.field(i,"dlvSendCloseTmpltNo");if(!template.isBlank()&&catalog.shippingTemplates(actor).stream().noneMatch(t->t.id().equals(template)))throw invalid("발송마감 템플릿을 다시 선택해 주세요.");}
 private Step step(Long actor,Type type,String option,String method,String path,String body,Map<String,?> before,Map<String,?> after){return new Step(UUID.randomUUID().toString(),type,option,method,path,"",body,json.writeValueAsString(comparable(actor,before)),json.writeValueAsString(comparable(actor,after)));}
 private Map<String,Object> priceGroup(Map<String,Object> all,Set<String> keys){var out=new LinkedHashMap<String,Object>();for(String key:keys)out.put("fields."+key,all.get("fields."+key));return out;}
 private Map<String,Object> selected(Map<String,Object> all,List<MarketplaceEditing.Change> changes){var out=new LinkedHashMap<String,Object>();for(var c:changes){String key=c.path().substring(8);out.put(key,all.get(key));}return out;}
 private void check(Mapping m){if(m!=null&&!accountKey().equals(m.accountKey()))throw invalid("11번가 계정이 변경되었습니다.");}
 public Result execute(Long actor,Prepared p,Step step,Mapping mapping){return execute(actor,p,step,mapping,s->{});}
 public Result execute(Long actor,Prepared p,Step step,Mapping mapping,Consumer<Step> beforeDispatch){access.productActor(actor,true);check(mapping);if(!accountKey().equals(p.accountKey())||!p.steps().contains(step))return result(State.FAILED,mapping,"ACCOUNT_CHANGED",null);
  if(step.type()==Type.CREATE&&mapping!=null&&mapping.sellerProductId()!=null)return result(State.FAILED,mapping,"ALREADY_REGISTERED",null);
  boolean[] dispatched={false};try{if(step.type()!=Type.CREATE){var live=docs.observe(actor,p.editIntent().observed(),mapping);if(matches(actor,docs.input(live),mapping,step,true))return result(State.CONFIRMED,mapping,"CONFIRMED",step.bodyJson());if(!matches(actor,docs.input(live),mapping,step,false))return result(State.FAILED,mapping,"BASELINE_CHANGED",null);}
   else{var desired=docs.apply(p.editIntent().observed(),p.editIntent().changes());inspection.require(actor,docs.images(desired,Set.of()));}
   if(step.type()!=Type.CREATE&&step.type()!=Type.PRICE&&step.type()!=Type.STOCK){var desired=docs.apply(p.editIntent().observed(),p.editIntent().changes());var oldUrls=docs.images(p.editIntent().observed(),Set.of()).stream().map(ImageInspection.Input::url).collect(java.util.stream.Collectors.toSet());inspection.require(actor,docs.images(desired,oldUrls));}
   var response=catalog.client.request(step.method(),step.path(),step.bodyJson(),true,()->{beforeDispatch.accept(step);dispatched[0]=true;});
   if(response.status()>=500)return result(State.UNKNOWN,mapping,"RESULT_UNKNOWN",step.bodyJson());if(response.status()<200||response.status()>=300)return result(State.FAILED,mapping,"HTTP_"+response.status(),step.bodyJson());
   var root=catalog.client.root(response);String name=ElevenstXml.name(root),code=ElevenstXml.value(root,"resultCode");
   if(name.equals("ClientMessage")){if(!Set.of("200","210").contains(code))return result(code.equals("500")?State.FAILED:State.UNKNOWN,mapping,code.equals("500")?"REJECTED":"RESPONSE",step.bodyJson());String product=ElevenstXml.value(root,"productNo");if(step.type()==Type.CREATE)mapping=new Mapping(accountKey(),ElevenstClient.id(product),List.of());else if(step.type()!=Type.STOCK&&!mapping.sellerProductId().equals(product))return result(State.UNKNOWN,mapping,"MAPPING_CHANGED",step.bodyJson());}
   else if(!step.path().contains("updateProductDetailCont")||!name.equals("Product"))return result(State.UNKNOWN,mapping,"RESPONSE",step.bodyJson());
   return reconcile(actor,p,step,result(State.ACCEPTED,mapping,"ACCEPTED",step.bodyJson()));
  }catch(cc.ataglace.molebutter.common.api.InputValidationFailure e){return result(dispatched[0]?State.UNKNOWN:State.FAILED,mapping,dispatched[0]?"RESULT_UNKNOWN":"BASELINE_CHANGED",dispatched[0]?step.bodyJson():null);}catch(MarketplaceFailure e){boolean rejected=e.kind()==MarketplaceFailure.Kind.AUTHENTICATION||e.kind()==MarketplaceFailure.Kind.PERMISSION;return result(dispatched[0]&&!rejected?State.UNKNOWN:State.FAILED,mapping,dispatched[0]?rejected?e.kind().name():"RESULT_UNKNOWN":"PREFLIGHT_"+e.kind().name(),dispatched[0]?step.bodyJson():null);}
 }
 public Result reconcile(Long actor,Prepared p,Step step,Result previous){access.productActor(actor,true);check(previous.mapping());var mapping=previous.mapping();
  if(!accountKey().equals(p.accountKey()))return result(State.FAILED,mapping,"ACCOUNT_CHANGED",previous.requestJson());
  if(mapping==null||mapping.sellerProductId()==null)return result(State.UNKNOWN,mapping,"CREATE_UNCONFIRMED",previous.requestJson());
  try{var snapshot=catalog.snapshot(mapping.sellerProductId());if(step.type()==Type.CREATE){
    var desired=docs.input(docs.apply(p.editIntent().observed(),p.editIntent().changes()));var links=new ArrayList<OptionMapping>();
    for(var o:desired.options()){
     var existing=mapping.options().stream().filter(link->link.optionId().equals(o.id())).findFirst();String code="MB"+o.id().replace("-","");
     var found=snapshot.stocks().stream().filter(s->existing.isPresent()?existing.get().sellerProductItemId().equals(s.remoteId()):s.sellerCode().equals(code)||desired.options().size()==1&&o.name().equals("단일 상품")&&snapshot.stocks().size()==1).toList();
     if(found.size()!=1)return result(State.ACCEPTED,mapping,"OPTIONS_UNCONFIRMED",previous.requestJson());links.add(new OptionMapping(o.id(),found.getFirst().remoteId(),null));
    }
    var verified=new Mapping(accountKey(),mapping.sellerProductId(),List.copyOf(links));
    if(snapshot.stocks().size()!=links.size()||!MarketplaceCreationConfirmation.completeOptions(verified,desired.options().stream().map(PartnerEditor.Option::id).toList(),false))return result(State.ACCEPTED,mapping,"OPTIONS_UNCONFIRMED",previous.requestJson());
    mapping=verified;
    if(Set.of("101","102").contains(snapshot.status()))return result(State.ACCEPTED,mapping,"APPROVAL_PENDING",previous.requestJson());
    if(!Set.of("103","104","105","106").contains(snapshot.status()))return result(State.ACCEPTED,mapping,"CREATE_STATUS_UNCONFIRMED",previous.requestJson());
    return result(State.CONFIRMED,mapping,"CREATED_CONFIRMED",previous.requestJson());
   }
   var live=docs.observe(actor,p.editIntent().observed(),mapping);boolean reflected=matches(actor,docs.input(live),mapping,step,true);boolean imageReview=!reflected&&json.readTree(step.expectedJson()).has("images")&&matches(actor,docs.input(live),mapping,step,true,true);return result(reflected?State.CONFIRMED:State.ACCEPTED,mapping,imageReview?"IMAGE_REVIEW_REQUIRED":"REFLECTION_CHECK",previous.requestJson());
  }catch(MarketplaceFailure|cc.ataglace.molebutter.common.api.InputValidationFailure e){return result(State.ACCEPTED,mapping,"VERIFY_UNAVAILABLE",previous.requestJson());}
 }
 private boolean matches(Long actor,PartnerEditor.Input i,Mapping mapping,Step step,boolean expected){return matches(actor,i,mapping,step,expected,false);}
 private boolean matches(Long actor,PartnerEditor.Input i,Mapping mapping,Step step,boolean expected,boolean ignoreImages){var wanted=comparable(actor,json.convertValue(json.readTree(expected?step.expectedJson():step.baselineJson()),Map.class));if(step.type()==Type.STOCK){var o=i.options().stream().filter(v->v.id().equals(step.optionId())).findFirst();return o.isPresent()&&Objects.equals(o.get().quantity(),wanted.path("quantity").asString());}var values=comparable(actor,parts(i));for(var e:wanted.properties())if(!(ignoreImages&&e.getKey().equals("images"))&&!Objects.equals(values.path(e.getKey()).isMissingNode()?json.nullNode():values.path(e.getKey()),e.getValue()))return false;return true;}
 // Marketplace reads cannot return the editor's UUID or asset ID. Compare transmitted values.
 private tools.jackson.databind.node.ObjectNode comparable(Long actor,Map<String,?> values){
  var out=json.valueToTree(values).asObject();var images=out.path("images");if(images.isArray()){var sorted=new ArrayList<tools.jackson.databind.JsonNode>();images.forEach(sorted::add);sorted.sort(Comparator.comparing((tools.jackson.databind.JsonNode i)->!i.path("representative").asBoolean()).thenComparingInt(i->i.path("order").asInt()));var rows=json.createArrayNode();for(var image:sorted){String asset=image.path("assetId").asString("");String url=asset.isBlank()?image.path("url").asString():assets.submissionUrl(actor,asset);rows.add(json.createObjectNode().put("url",url).put("representative",image.path("representative").asBoolean()).put("order",rows.size()));}out.set("images",rows);}
  if(out.path("description").isString()){var matcher=java.util.regex.Pattern.compile("/api/marketplaces/assets/([a-fA-F0-9-]{36})").matcher(out.path("description").asString());var html=new StringBuffer();while(matcher.find())matcher.appendReplacement(html,java.util.regex.Matcher.quoteReplacement(assets.submissionUrl(actor,matcher.group(1))));matcher.appendTail(html);out.put("description",html.toString());}return out;
 }

 private Result result(State state,Mapping mapping,String code,String request){return new Result(state,mapping,code,switch(code){case "CREATED_CONFIRMED"->"11번가 상품번호·옵션번호와 판매 상태를 확인했습니다. 최신 값은 상품 탭에서 다시 조회해 주세요.";case "IMAGE_REVIEW_REQUIRED"->"11번가 조회 이미지 주소가 전송 주소와 다릅니다. WebP 변환 등으로 자동 비교할 수 없어 판매자센터에서 이미지 반영 확인이 필요합니다. 재전송하지 마세요.";case "APPROVAL_PENDING"->"11번가 승인 대기 중입니다.";case "OPTIONS_UNCONFIRMED"->"등록 상품은 확인했으나 옵션 연결 확인이 필요합니다. 재등록하지 마세요.";case "CREATE_UNCONFIRMED","RESULT_UNKNOWN"->"등록 결과를 확인할 수 없습니다. 중복 등록 방지를 위해 재전송하지 않습니다.";case "BASELINE_CHANGED"->"최신 마켓 값이 달라졌거나 입력이 유효하지 않습니다. 다시 조회 후 변경 내용을 확인해 주세요.";case "CONFIRMED","REFLECTION_CHECK"->state==State.CONFIRMED?"선택한 변경값의 반영을 확인했습니다.":"선택한 변경값의 반영을 확인 중입니다.";default->"11번가 실행 결과를 확인해 주세요.";},Instant.now(),request);}
}
